package server
import("encoding/json";"net/http";"os";"github.com/uncensored404/404sec-dofus/internal/builds";"github.com/uncensored404/404sec-dofus/internal/damage";"github.com/uncensored404/404sec-dofus/internal/xp")
type Server struct{buildsPath string};func New(p string)*Server{return &Server{p}}
func write(w http.ResponseWriter,code int,v any){w.Header().Set("Content-Type","application/json; charset=utf-8");w.Header().Set("X-Content-Type-Options","nosniff");w.WriteHeader(code);_ = json.NewEncoder(w).Encode(v)}
func decode(r *http.Request,v any)error{defer r.Body.Close();return json.NewDecoder(http.MaxBytesReader(nil,r.Body,1<<20)).Decode(v)}
func(s *Server)Handler()http.Handler{m:=http.NewServeMux();m.HandleFunc("GET /health",func(w http.ResponseWriter,r *http.Request){write(w,200,map[string]any{"ok":true,"service":"404sec-dofus"})});m.HandleFunc("GET /api/v1/builds",func(w http.ResponseWriter,r *http.Request){b,e:=builds.Load(s.buildsPath);if e!=nil{write(w,500,map[string]string{"error":"build data unavailable"});return};write(w,200,b)});m.HandleFunc("POST /api/v1/damage",func(w http.ResponseWriter,r *http.Request){var in damage.Input;if e:=decode(r,&in);e!=nil{write(w,400,map[string]string{"error":"invalid JSON"});return};out,e:=damage.Calculate(in);if e!=nil{write(w,400,map[string]string{"error":e.Error()});return};write(w,200,out)});m.HandleFunc("POST /api/v1/xp",func(w http.ResponseWriter,r *http.Request){var in struct{Current int64 `json:"current"`;Target int64 `json:"target"`};if e:=decode(r,&in);e!=nil{write(w,400,map[string]string{"error":"invalid JSON"});return};out,e:=xp.Plan(in.Current,in.Target);if e!=nil{write(w,400,map[string]string{"error":e.Error()});return};write(w,200,out)});m.HandleFunc("GET /",func(w http.ResponseWriter,r *http.Request){b,e:=os.ReadFile("web/index.html");if e!=nil{http.Error(w,"Dashboard file missing",500);return};w.Header().Set("Content-Type","text/html; charset=utf-8");w.Header().Set("X-Frame-Options","DENY");_,_=w.Write(b)});return m}
